/**
 * The provenance header every generated file opens with.
 *
 * A generated file that does not say where it came from is a file somebody edits.
 * One helper, so the banner cannot drift between the app tree, the Run API modules
 * and the contract-test assets — and so a reviewer grepping "Generated by" finds
 * every emitted file.
 */
export function generatedHeader(generatorVersion: string, source: string): string {
  return `// Generated by @fde/runtime-generator-mastra ${generatorVersion} — do not hand-edit.\n// Source: ${source}\n`;
}
